// Tạo yêu cầu lấy chi tiết đơn mới (người mua, SKU, tổng tiền)
const ev = $input.first().json;
const id = ev.data && ev.data.order_id;
if (!id) throw new Error('Sự kiện không có order_id');
return [{ json: { method: 'GET', path: '/order/202309/orders', query: { ids: String(id) } } }];

const ev = $('Router gọi tới').first().json;
const r = $input.first().json;
if (!r.ok) throw new Error(`Ghi nhận mua kèm: lấy chi tiết đơn lỗi ${r.code} ${r.message}`);
const o = (r.data.orders || [])[0] || {};
const skus = [...new Set((o.line_items || []).map((i) => i.seller_sku).filter(Boolean))];
return [{ json: { order_id: String(ev.data.order_id), buyer_user_id: o.user_id ? String(o.user_id) : '',
  skus, total_amount: o.payment && o.payment.total_amount ? String(o.payment.total_amount) : '' } }];
